const url = new URL('https://zernio.com/api/v1/connect/facebook');
url.searchParams.set('profileId', process.env.ZERNIO_PROFILE_ID);
url.searchParams.set('redirect_url', `${AUTH_URL}/api/channels/zernio/facebook/callback`);
url.searchParams.set('headless', 'true');

const res = await fetch(url, {
  headers: { Authorization: `Bearer ${process.env.ZERNIO_API_KEY}` }
});
const { authUrl } = await res.json();
return NextResponse.json({ authorizeUrl: authUrl });

// 前端
const { authorizeUrl } = await fetch('/api/channels/zernio/facebook/connect', { method: 'POST' }).then(r => r.json());
window.location.href = authorizeUrl;

// /api/channels/zernio/facebook/callback
export async function GET(req: NextRequest) {
  const sp = req.nextUrl.searchParams;
  const oauthData = {
    profileId: sp.get('profileId'),
    tempToken: sp.get('tempToken'),
    connectToken: sp.get('connect_token'),
    userProfile: JSON.parse(decodeURIComponent(sp.get('userProfile') ?? ''))
  };
  // 暂存（cookie / session / 短 TTL Redis）
  const res = NextResponse.redirect(new URL('/social/settings/zernio-pages', req.url));
  res.cookies.set('zernio_oauth', JSON.stringify(oauthData), { httpOnly: true, maxAge: 600 });
  return res;
}

