// 前端调你后端，后端代理到 Zernio（不要把 API key 暴露到浏览器）
export async function POST(req: NextRequest) {
  const { pageId } = await req.json();
  const oauthData = JSON.parse(req.cookies.get('zernio_oauth')?.value ?? '{}');

  const r = await fetch('https://zernio.com/api/v1/connect/facebook/select-page', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${process.env.ZERNIO_API_KEY}`,
      'Content-Type': 'application/json',
      'X-Connect-Token': oauthData.connectToken
    },
    body: JSON.stringify({
      profileId: oauthData.profileId,
      pageId,
      tempToken: oauthData.tempToken,
      userProfile: oauthData.userProfile
    })
  });

  // 落 ChannelConnection（按 echo-app 现有 Meta 流程的模式）
  const result = await r.json();
  await prisma.channelConnection.create({ /* ... */ });
  return NextResponse.json({ ok: true });
}
